('4871a5b2-2479-536f-a069-d310f26bb12f', (select id from categories where name = 'Siyaset'), 'ku-kmr', 'Kîjan têgeh bi vê ravekirinê tê nasîn: "parvekirina desthilatê ji navendê ber bi herêm û rêveberiyên xweser ve"?', 'nenavendîbûn', 'xweseriya demokratîk', 'demokrasiya radîkal', 'hevpeymaniya demokratîk', 'A', '"nenavendîbûn" tê vê wateyê: parvekirina desthilatê ji navendê ber bi herêm û rêveberiyên xweser ve.', '"nenavendîbûn" tê vê wateyê: parvekirina desthilatê ji navendê ber bi herêm û rêveberiyên xweser ve.', '"ademi-merkeziyet" şu anlama gelir: iktidarın merkezden bölgelere ve özerk yönetimlere dağıtılması.', 1, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_curated_21601
