('a2cd1ed2-4317-5286-b841-e38ea4d84488', (select id from categories where name = 'Siyaset'), 'ku-kmr', 'Binirxîne: li gorî vê ravekirinê "muxalefeta civakî" ev e — redkirina eşkere û bêşiddet a qanûneke ku neheq tê dîtin. Rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "bêîtaetiya sivîl" e; "muxalefeta civakî" tê vê wateyê: nerazîbûna ku ji hêla komên civakî ve tê nîşandan, ne ji hêla partiyan ve.', 'Na — ev ravekirina "bêîtaetiya sivîl" e; "muxalefeta civakî" tê vê wateyê: nerazîbûna ku ji hêla komên civakî ve tê nîşandan, ne ji hêla partiyan ve.', 'Hayır — bu tanım "bêîtaetiya sivîl" kavramına ait; "muxalefeta civakî" şu anlama gelir: partilerin değil toplumsal kesimlerin gösterdiği hoşnutsuzluk.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_siy_0020
