('27455f64-0f30-53f7-94d5-5146cd519024', (select id from categories where name = 'Siyaset'), 'ku-kmr', '"garantiya destûrî" girêdana mafekî bi destûra bingehîn e da ku bi qanûneke asayî neyê rakirin. Ev rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. "garantiya destûrî" girêdana mafekî bi destûra bingehîn e da ku bi qanûneke asayî neyê rakirin. "dadgehkirina dadperwer" têgeheke cuda ye: mafê her kesî yê darizandina eşkere, bêalî û di demeke maqûl de ye.', 'Rast e. "garantiya destûrî" girêdana mafekî bi destûra bingehîn e da ku bi qanûneke asayî neyê rakirin. "dadgehkirina dadperwer" têgeheke cuda ye: mafê her kesî yê darizandina eşkere, bêalî û di demeke maqûl de ye.', 'Doğru. "garantiya destûrî", bir hakkın sıradan yasayla kaldırılamaması için anayasaya bağlanmasıdır. "dadgehkirina dadperwer" ayrı bir kavramdır: herkesin açık, tarafsız ve makul sürede yargılanma hakkıdır.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_siy_0027
