('092cb4b3-839f-53c3-a110-4dd2c3f3a4e0', (select id from categories where name = 'Siyaset'), 'ku-kmr', 'Rast e an şaş e: "aştiya civakî" rewşa ku tê de nakokî bi şîdetê nayên çareserkirin e.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. "aştiya civakî" rewşa ku tê de nakokî bi şîdetê nayên çareserkirin e. Ji bilî vê "lihevkirina civakî" jî heye; ew peymana bêyaz e ku komên cuda li ser jiyana hevpar digihîjin hev.', 'Rast e. "aştiya civakî" rewşa ku tê de nakokî bi şîdetê nayên çareserkirin e. Ji bilî vê "lihevkirina civakî" jî heye; ew peymana bêyaz e ku komên cuda li ser jiyana hevpar digihîjin hev.', 'Doğru. "aştiya civakî", çatışmaların şiddetle çözülmediği toplumsal durumdur. Bunun yanında "lihevkirina civakî" de vardır; o, farklı kesimlerin ortak yaşam üzerinde vardığı yazısız uzlaşıdır.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_siy_0041
