('54116578-f5ee-53e9-92ff-352703c414db', (select id from categories where name = 'Siyaset'), 'ku-kmr', 'Rast e an şaş e: "beşdariya siyasî" hevkariya hêzên cuda yên civakê ye li ser bernameyeke hevpar.', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "hevpeymaniyên demokratîk" e; "beşdariya siyasî" tevlîbûna hemwelatiyan e di biryar û çavdêriya rêveberiyê de.', 'Na — ev ravekirina "hevpeymaniyên demokratîk" e; "beşdariya siyasî" tevlîbûna hemwelatiyan e di biryar û çavdêriya rêveberiyê de.', 'Hayır — bu tanım "hevpeymaniyên demokratîk" kavramına aittir; "beşdariya siyasî" ise yurttaşların karara ve yönetimin denetimine katılmasıdır.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_siy_0048
('605c76f1-31bc-5656-ad0e-06a0974275c7', (select id from categories where name = 'Siyaset'), 'ku-kmr', '"mafên demokratîk" komek mafan in wekî azadiya gotin, civîn û rêxistinbûnê. Ev rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. "mafên demokratîk" komek mafan in wekî azadiya gotin, civîn û rêxistinbûnê. "hevpeymaniyên demokratîk" têgeheke cuda ye; ew hevkariya hêzên cuda yên civakê ne li ser bernameyeke hevpar.', 'Rast e. "mafên demokratîk" komek mafan in wekî azadiya gotin, civîn û rêxistinbûnê. "hevpeymaniyên demokratîk" têgeheke cuda ye; ew hevkariya hêzên cuda yên civakê ne li ser bernameyeke hevpar.', 'Doğru. "mafên demokratîk", ifade, toplanma ve örgütlenme özgürlüğü gibi haklar bütünüdür. "hevpeymaniyên demokratîk" ayrı bir kavramdır; o, toplumun farklı güçlerinin ortak program üzerinde iş birliğidir.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_siy_0051
('1c6204ca-842c-55eb-9e17-8b19219c3c43', (select id from categories where name = 'Siyaset'), 'ku-kmr', 'Binirxîne: li gorî vê ravekirinê "mafên demokratîk" ev e — biryardayîna gel bi xwe, bêyî navbeynkariya nûneran. Rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "beşdariya rasterast" e; "mafên demokratîk" tê vê wateyê: komek mafên wekî azadiya gotin, civîn û rêxistinbûnê.', 'Na — ev ravekirina "beşdariya rasterast" e; "mafên demokratîk" tê vê wateyê: komek mafên wekî azadiya gotin, civîn û rêxistinbûnê.', 'Hayır — bu tanım "beşdariya rasterast" kavramına ait; "mafên demokratîk" şu anlama gelir: ifade, toplanma ve örgütlenme özgürlüğü gibi haklar bütünü.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_siy_0052
('0a63c66d-5e62-5082-816f-7c0c6f8ee975', (select id from categories where name = 'Siyaset'), 'ku-kmr', 'Ev ravekirin ji bo "beşdariya rasterast" rast e an şaş e: saziya hilbijartî ya ku karûbarên bajêr an gund birêve dibe?', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "rêveberiya herêmî" ye; "beşdariya rasterast" tê vê wateyê: biryardayîna gel bi xwe, bêyî navbeynkariya nûneran.', 'Na — ev ravekirina "rêveberiya herêmî" ye; "beşdariya rasterast" tê vê wateyê: biryardayîna gel bi xwe, bêyî navbeynkariya nûneran.', 'Hayır — bu tanım "rêveberiya herêmî" kavramına ait; "beşdariya rasterast" şu anlama gelir: halkın temsilci aracılığı olmadan doğrudan karar vermesi.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()) -- yerel: offline_tf_siy_0054
